    "title": "大家好，我是徐浪。好久不见朋友，得一两年了吧？先别骂……咱讲点儿组织和纪律，让我先说两句，最后咱在评论区统一发泄。最近我研究了个挺玄学的东西，神神叨叨挺吓人的，本来想今天给大家讲讲，结果临时有个挺急的事儿需要解决，那就下周再讲吧，反正我也不着急，你们更是了，一两年没见不差这两天儿了。那就下周二晚22点不见不散吧，咱整点儿玄的神神鬼鬼的。就这样，评论区聊几句，有啥想问的就问，尽量少骂两句！",
